<script lang="ts">
 import {t} from './i18n';
 import {base} from './consoleBase';
 import {sectionHref,workspaceHref} from './workspaceArchitecture';
 import BillingOverview from './BillingOverview.svelte';
 export let tenant:string;
 export let name:string;
 export let activation:{active:boolean;status:string}|null;
 export let configured:boolean|null=null;
 export let activityReady=false,activityLoading=false;
 export let permissions:string[]=[];
 export let apiPrefix='';
 export let insights:{kpis:{inbound:number;sessions:number;leads:number};sales_funnel:{active:number;won:number;handoffs:number};leads:{lead_id:string;name?:string|null;phone?:string|null;status:string;updated_utc:string}[]};
 const may=(permission:string)=>permissions.includes(permission);
 $: analytics=permissions.includes('analytics.read');
 $: active=activation?.active===true;
