  {#if analytics && activityReady}<section class="home-card"><header><div><h3>{$t('Recent enquiries')}</h3><p>{$t('Your latest recorded leads. Open Sales to manage the next step.')}</p></div><a href={sectionHref(base,'pipeline',tenant)}>{$t('View sales')} →</a></header><div class="enquiries">{#each insights.leads.slice(0,5) as lead}<a href={sectionHref(base,'pipeline',tenant)}><span class="person" aria-hidden="true">{(lead.name||'?').charAt(0).toUpperCase()}</span><div><strong>{lead.name||lead.phone||$t('Customer enquiry')}</strong><small>{new Date(lead.updated_utc).toLocaleDateString()}</small></div><span class="lead-status">{lead.status}</span></a>{:else}<div class="empty"><h4>{$t('Ready for your first enquiry')}</h4><p>{$t('Customer leads will appear here when contact details are shared with your assistant.')}</p></div>{/each}</div></section>{/if}
