 </div>
 <aside class="home-side">{#if may('view_costs')}{#key tenant}<BillingOverview {tenant} compact canViewCosts {apiPrefix}/>{/key}{/if}<section class="home-card knowledge-card"><span class="knowledge-mark" aria-hidden="true">✳</span><h3>{$t('Good answers start with your business')}</h3><p>{$t('Keep prices, opening hours and frequently asked questions up to date. Your assistant uses this saved information across connected channels.')}</p>{#if may('business_settings.read')}<a href={sectionHref(base,'profile',tenant)}>{$t('Review my business')} →</a>{/if}</section></aside>
</div>

